class Writer(object):
    """Bounded pipe friendly byte writer with explicit flushing."""

    __slots__ = ('fileno', 'pending', 'emitted')

    def __init__(self):
        try:
            self.fileno = sys.stdout.fileno()
        except Exception:
            self.fileno = 1
        self.pending = bytearray()
        self.emitted = False

    def write(self, text):
        buffer = self.pending
        buffer += text.encode('utf-8')
        self.emitted = True
        if len(buffer) >= 1 << 16:
            self.flush()

    def flush(self):
        buffer = self.pending
        if not buffer:
            return
        view = memoryview(buffer)
        size = len(buffer)
        done = 0
        fileno = self.fileno
        while done < size:
            try:
                done += os.write(fileno, view[done:])
            except BlockingIOError:
                select.select([], [fileno], [])
            except InterruptedError:
                continue
        view.release()
        del buffer[:]

    @property
    def started(self):
        return self.emitted


