def solve(data):
    try:
        if len(data) > INPUT_CAP:
            return {'error': 'invalid'}
        text = data.decode('utf-8')
    except Exception:
        return {'error': 'invalid'}
    if text.startswith('\ufeff'):
        return {'error': 'invalid'}
    try:
        request = json.loads(text, object_pairs_hook=_unique,
                             parse_constant=_constant, parse_float=_number)
    except Exception:
        return {'error': 'invalid'}
    text = None
    data = None
    try:
        if (type(request) is not dict or len(request) != 1
                or type(request.get('jobs')) is not list
                or len(request['jobs']) > MAX_JOBS):
            return {'error': 'invalid'}
        if not _bounded(request, 1):
            return {'error': 'invalid'}
    except Exception:
